const TAROT_MAJOR=[{n:"愚者",ukw:"新开始/冒险/自由",umean:"全新旅程的起点，保持好奇心，大胆迈出第一步。",rkw:"鲁莽/逃避/拖延",rmean:"冲动行事或害怕未知，需要停下来想清楚。"},{n:"魔术师",ukw:"创造力/行动力/资源",umean:"你拥有实现目标所需的一切，善用手头资源。",rkw:"操纵/才华浪费/犹豫",rmean:"才能未被利用，或有用错方向之嫌。"},{n:"女祭司",ukw:"直觉/潜意识/静默",umean:"倾听内心声音，答案已在你心中。",rkw:"压抑直觉/秘密/浮躁",rmean:"忽略了直觉，或被表面信息迷惑。"},{n:"女皇",ukw:"丰饶/母性/感官享受",umean:"滋养与收获的时期，享受生活之美。",rkw:"过度依赖/停滞/自我忽视",rmean:"在关系或物质上过于执着，或忽略了自我关怀。"},{n:"皇帝",ukw:"权威/结构/稳定",umean:"建立秩序与规则，稳固你的根基。",rkw:"专制/僵化/控制欲",rmean:"过于强硬或固执，需要灵活一些。"},{n:"教皇",ukw:"传统/信仰/导师",umean:"遵循既有规则，或向有经验者学习。",rkw:"束缚/伪传统/质疑",rmean:"在质疑成规，或遇到了不合适的导师。"},{n:"恋人",ukw:"爱/选择/和谐",umean:"面临重要选择，跟随真心。",rkw:"失衡/错误选择/关系破裂",rmean:"关系中存在矛盾，或选择时不够诚实。"},{n:"战车",ukw:"意志/胜利/前进",umean:"掌控方向，克服障碍，胜利在望。",rkw:"失控/方向迷失/内耗",rmean:"同时朝多个方向用力，需要集中精力。"},{n:"力量",ukw:"勇气/耐心/内在力量",umean:"以柔克刚，用耐心而非蛮力解决问题。",rkw:"自我怀疑/软弱/冲动",rmean:"对自己缺乏信心，或情绪失控。"},{n:"隐士",ukw:"内省/独处/寻求真理",umean:"需要独处思考，点亮自己的灯。",rkw:"孤立/逃避/不愿求助",rmean:"过度与世隔绝，或拒绝他人帮助。"},{n:"命运之轮",ukw:"转折/循环/机遇",umean:"运势正在转变，顺势而为。",rkw:"厄运/抗拒变化/失控",rmean:"正经历低谷或抗拒必然的改变。"},{n:"正义",ukw:"公正/真相/因果",umean:"事出有因，做出公正的判断。",rkw:"不公/逃避责任/偏见",rmean:"需要承担责任，或存在不公之事。"},{n:"倒吊人",ukw:"牺牲/换角度/等待",umean:"换个角度看问题，暂时的停顿有意义。",rkw:"无谓牺牲/停滞/执念",rmean:"牺牲没有回报，或卡在原地太久。"},{n:"死神",ukw:"结束/转变/重生",umean:"旧阶段结束，新篇章即将开始。",rkw:"抗拒结束/停滞/放不下",rmean:"紧抓过去不放，阻碍了新生。"},{n:"节制",ukw:"平衡/节制/调和",umean:"找到中庸之道，耐心调和各方。",rkw:"失衡/极端/不耐",rmean:"生活或情绪走向极端，需要找回平衡。"},{n:"恶魔",ukw:"欲望/束缚/物质迷恋",umean:"认清什么在束缚你，欲望是把双刃剑。",rkw:"解脱/觉醒/挣脱",rmean:"开始意识到束缚并寻求自由。"},{n:"塔",ukw:"突变/崩塌/启示",umean:"旧有结构突然瓦解，虽然痛苦但带来真相。",rkw:"避免灾难/内隐动摇/侥幸",rmean:"隐患尚未爆发，但需要警惕。"},{n:"星星",ukw:"希望/疗愈/信心",umean:"黑暗过后是希望，治愈正在发生。",rkw:"失望/信心动摇/空虚",rmean:"对未来失去信心，或期望过高。"},{n:"月亮",ukw:"幻象/不安/潜意识",umean:"事情不清晰，跟随直觉但保持警惕。",rkw:"迷雾散去/揭露/释放恐惧",rmean:"误解澄清，或恐惧逐渐消散。"},{n:"太阳",ukw:"快乐/成功/活力",umean:"光明、成功与喜悦，大胆展现自己。",rkw:"暂时低落/过度乐观/延迟",rmean:"成功会来但稍晚，或需要调整预期。"},{n:"审判",ukw:"觉醒/复盘/召唤",umean:"回顾过去，做出重要的觉醒决定。",rkw:"自我批判/逃避召唤/悔恨",rmean:"难以原谅自己，或在逃避内心的呼唤。"},{n:"世界",ukw:"完成/圆满/整合",umean:"一个周期圆满完成，准备迎接新旅程。",rkw:"未完成/延迟/半途而废",rmean:"还差最后一步，不要在终点前放弃。"}],TAROT_SUITS=[{key:"wands",name:"权杖",element:"火",kw:"行动/热情/创造"},{key:"cups",name:"圣杯",element:"水",kw:"情感/关系/直觉"},{key:"swords",name:"宝剑",element:"风",kw:"思想/冲突/真相"},{key:"pentacles",name:"星币",element:"土",kw:"物质/工作/安全"}],TAROT_RANKS=["Ace","二","三","四","五","六","七","八","九","十","侍从","骑士","王后","国王"],TAROT_RANK_U={Ace:"新开始/机遇",二:"选择/平衡",三:"初步进展/合作",四:"稳定/休息",五:"冲突/失落",六:"和谐/胜利",七:"策略/幻想",八:"快速/移动",九:"接近成功/顾虑",十:"完成/负担",侍从:"消息/学习/好奇",骑士:"行动/追求/冒险",王后:"成熟/感受/包容",国王:"掌控/领导/权威"},TAROT_RANK_R={Ace:"延迟/错失",二:"犹豫/失衡",三:"计划不周/分歧",四:"停滞/吝啬",五:"和解/走出低谷",六:"恶运/怀旧",七:"自欺/策略失误",八:"拖延/被困",九:"焦虑/孤立",十:"结束/解脱",侍从:"幼稚/抔消息",骑士:"鲁莽/迟到",王后:"情绪不稳/占有欲",国王:"专制/冷酷"};
;
function buildMinor(){const out=[];return TAROT_SUITS.forEach(s=>{TAROT_RANKS.forEach((r,i)=>{out.push({name:`${s.name}${r}`,suit:s.name,rank:r,ukw:`${s.kw.split("/")[0]}·${TAROT_RANK_U[r].split("/")[0]}`,umean:`${s.element}元素主题：${s.kw}。牌义偏向${TAROT_RANK_U[r]}。`,rkw:`${TAROT_RANK_R[r].split("/")[0]}`,rmean:`逆位提示${TAROT_RANK_R[r]}，需要警惕${s.name}能量的失衡。`})})}),out}
;
const TAROT_DECK=[...TAROT_MAJOR.map((m,i)=>({name:`大阿卡纳·${m.n}`,suit:"大阿卡纳",rank:i+1,...m})),...buildMinor()],TAROT_SPREADS={single:{label:"单张·今日提示",n:1,positions:["今日指引"]},three:{label:"三张·时间之流",n:3,positions:["过去","现在","未来"]},choice:{label:"二选一·决策",n:3,positions:["现状","选择 A","选择 B"]},mind:{label:"四牌·身心灵",n:4,positions:["身体","情感","思想","整体"]}};
;
function tarotShuffle(deck){const d=deck.slice();for(let i=d.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[d[i],d[j]]=[d[j],d[i]]}return d.map(c=>({...c,reversed:Math.random()<.5}))}
;
function viewTarot(){const rec=DB.data.tarot||{},picks=rec.picks||[],spread=rec.spread||"single",c=`<div class="p-panel tarot-module"><div class="yj-head"><div class="yj-kicker">TAROT</div><h2>塔罗占卜</h2><p class="yj-note">心诚则灵，默念所问之事，牌会给出提示。解读仅供参考，不做人生决策依据。</p></div>
  <section class="yj-card"><h3>开始占卜</h3>
    <label class="fl">所问之事（可留空）</label>
    <input id="tarot-q" type="text" maxlength="60" placeholder="如：这段关系该继续吗" value="${esc(rec.question||"")}" style="width:100%;margin:6px 0 12px;background:var(--pt-input);border:1px solid var(--pt-border);border-radius:8px;padding:9px 12px;color:var(--pt-text);outline:none;font-size:14px">
    <label class="fl">选择牌阵</label>
    <div class="tarot-spreads">${Object.entries(TAROT_SPREADS).map(([k,v])=>`<label class="tarot-spread ${spread===k?"on":""}" data-spread="${k}"><input type="radio" name="tarot-spread" value="${k}" ${spread===k?"checked":""} style="display:none"><b>${v.label}</b><small>${v.n}张</small></label>`).join("")}</div>
    <div style="margin-top:14px;display:flex;gap:8px"><button class="btn btn-orange" id="tarot-draw">开始抽牌</button>${picks.length?'<button class="btn btn-ghost" id="tarot-reset">重新抽牌</button>':""}</div>
  </section>
  ${picks.length?`<section class="yj-card"><h3>${rec.question?`「${esc(rec.question)}」`:""} 牌阵结果</h3>
    <div class="tarot-board n-${picks.length}">${picks.map((p,i)=>`<div class="tarot-card ${p.reversed?"rev":""}" style="--d:${i*.18}s"><div class="tc-inner"><div class="tc-face tc-front"><small>${esc(TAROT_SPREADS[spread].positions[i])}</small><h4>${esc(p.name)}</h4><span class="tc-dir">${p.reversed?"逆位":"正位"}</span><p class="tc-kw">${p.reversed?esc(p.rkw):esc(p.ukw)}</p><p class="tc-mean">${p.reversed?esc(p.rmean):esc(p.umean)}</p></div></div></div>`).join("")}</div>
    <div class="tarot-summary"><h4>整体提示</h4><p>${tarotSummary(spread,picks)}</p></div>
  </section>`:""}
  </div>`;return portalShell("tarot",c)}
;
function tarotSummary(spread,picks){if(spread==="single"){const p=picks[0];return`${p.name}${p.reversed?"（逆位）":""}——${p.reversed?p.rkw:p.ukw}。${p.reversed?p.rmean:p.umean}`}if(spread==="three"){const[a,b,c]=picks;return`过去：${a.name}${a.reversed?"逆":""}，${a.reversed?a.rkw:a.ukw}；现在：${b.name}${b.reversed?"逆":""}，${b.reversed?b.rkw:b.ukw}；未来走向${c.name}${c.reversed?"逆":""}，${c.reversed?c.rkw:c.ukw}。综合来看，先接纳过去，专注当下，未来自会明朗。`}if(spread==="choice"){const[a,b,c]=picks;return`现状是${a.name}${a.reversed?"逆":""}（${a.reversed?a.rkw:a.ukw}）。选择A倾向${b.name}${b.reversed?"逆":""}（${b.reversed?b.rkw:b.ukw}）；选择B倾向${c.name}${c.reversed?"逆":""}（${c.reversed?c.rkw:c.ukw}）。哪一边更贴近你内心的真实感受，就选哪边。`}if(spread==="mind"){const[a,b,c,d]=picks;return`身体状态：${a.name}${a.reversed?"逆":""}；情感：${b.name}${b.reversed?"逆":""}；思想：${c.name}${c.reversed?"逆":""}；整体提示：${d.name}${d.reversed?"逆":""}（${d.reversed?d.rkw:d.ukw}）。`}return""}
;
const HUANG_DAXIAN_SIGNS=[{id:1,level:"上上",title:"姜公封相",poem:"灵签求得第一枝，龙虎风云际会时。一旦凌霄扬自乐，任君来往赴瑶池。",story:"",readings:{事业:"功名可成，所谋之事大多亨通。",姻缘:"婚姻顺遂，有望成就。",财运:"求财丰盛。",健康:"疾病有望痊愈。",出行:"出行往来顺遂，所到之处皆合心意。",家宅:"家宅兴旺。",学业:"",流年:""}},{id:2,level:"上吉",title:"王道真误入桃源",poem:"枯木逢春尽发新，花香叶茂蝶来频。桃源竞斗千红紫，一叶渔舟误入津。",story:"",readings:{事业:"所谋之事有望获得福禄。",姻缘:"姻缘有缘分，有望成就。",财运:"求财可望。",健康:"疾病有望痊愈。",出行:"外出有机会意外遇见贵人。",家宅:"家宅安吉。",学业:"",流年:""}},{id:3,level:"中平",title:"鲁班伐木",poem:"牛山之木皆常美，独惜斧工尽伐他。大器大材无足用，矩规不准怎为槎。",story:"",readings:{事业:"名利须依理求取，不宜贪求。",姻缘:"婚姻不宜妄求。",财运:"求财应循正理，不可贪心。",健康:"求医须谨慎。",出行:"注意小人及口舌是非。",家宅:"宜修德积善。",学业:"",流年:""}},{id:4,level:"中吉",title:"燕子教飞",poem:"调雏紫燕在檐前，对语呢喃近午天。或往或来低复起，有时剪破绿杨烟。",story:"",readings:{事业:"谋事需要把握时机，不能盲目行动。",姻缘:"婚姻可求，进展渐渐明朗。",财运:"财运平稳，收益微薄。",健康:"身体方面宜多加谨慎。",出行:"外出需防小人及口舌是非。",家宅:"家宅平安。",学业:"",流年:""}},{id:5,level:"中吉",title:"陶渊明栽花",poem:"东园昨夜狂风急，万紫千红亦尽倾。幸有惜花人起早，培回根本复栽生。",story:"",readings:{事业:"名利暂时难成，需要等待时机，谋事宜谨慎。",姻缘:"婚姻进展迟疑，不宜操之过急。",财运:"财利微薄。",健康:"身体有恙须谨慎选择医生。",出行:"出行可能受阻，宜谨慎安排。",家宅:"家宅运势暂时不佳。",学业:"",流年:""}},{id:6,level:"上吉",title:"苏东坡游滕王阁",poem:"一片孤帆万里回，管弦呕哑且停杯。如云胜友谈风月，畅叙幽情极乐哉。",story:"",readings:{事业:"事业有成，所谋之事多能顺利。",姻缘:"婚姻有望成就。",财运:"财运丰盈，求财有利。",健康:"疾病有望痊愈。",出行:"出行顺遂，往来皆称心。",家宅:"家宅兴旺。",学业:"",流年:""}},{id:7,level:"中平",title:"丁山射雁",poem:"秋来征雁向南归，红叶纷纷满院飞。砧捣城头声切耳，江枫如火在渔矶。",story:"",readings:{事业:"",姻缘:"",财运:"",健康:"",出行:"",家宅:"",学业:"",流年:""}},{id:8,level:"下下",title:"鹊巢鸠居",poem:"鸣鸠争夺鹊巢居，宾主参差意不舒。满岭乔松萝蔦附，且猜诗语是何如。",story:"以鸠占鹊巢比喻原有居处被他人夺取，又以藤萝缠绕松树比喻受人牵制、依附他人的处境。",readings:{事业:"所谋之事不易成功，容易受到他人牵制。",姻缘:"婚姻不和谐，感情容易出现矛盾。",财运:"求财不宜冒进，更不可妄为。",健康:"自身容易受到疾病及口舌困扰。",出行:"出行容易遇阻，难以顺利完成。",家宅:"家宅运势不佳。",学业:"",流年:""}},{id:9,level:"上吉",title:"陶渊明赏菊",poem:"瑶琴一曲奏新腔，明月清风枕簟凉。咸集嘉宾同赏菊，或歌或舞或飞觞。",story:"陶渊明为晋代文人，不愿为五斗米折腰，辞官归隐，种菊赏菊，以田园生活寄托情怀。",readings:{事业:"不宜强求，顺其自然更为合适。",姻缘:"已有伴侣者感情和睦，未婚者有望遇到良缘。",财运:"不必刻意求财，财利自有来路。",健康:"春季可能有小恙，但有望很快恢复。",出行:"",家宅:"家庭和睦，生活安乐。",学业:"",流年:"大吉，尤其立秋之后较为有利。"}},{id:10,level:"中平",title:"苏秦不第",poem:"一轮月镜挂空中，偶被浮云障叠重。玉匣何时光气吐，谁人借我一狂风。",story:"",readings:{事业:"目前可能受到阻碍，宜等待机会，不可贸然行动。",姻缘:"感情容易出现不合，宜谨慎处理。",财运:"求财需要等待时机。",健康:"生病应谨慎选择医生。",出行:"外出应多加小心。",家宅:"家宅运势暂时不佳。",学业:"读书需要更加用功，暂不宜急于求成。",流年:""}},{id:11,level:"上吉",title:"汉文帝赏柳",poem:"杨柳垂堤锁绿烟，日长三起又三眠。往来紫燕纷飞舞，袅娜迎风倩我怜。",story:"",readings:{事业:"所谋之事多有吉利，名望有望提升。",姻缘:"婚姻良好，有望顺利成就。",财运:"求财可得。",健康:"疾病有望康复。",出行:"出行需防小人。",家宅:"家宅昌盛。",学业:"",流年:""}},{id:12,level:"下下",title:"蜃楼海市",poem:"蜃楼海市幻无边，万丈擎空接上天。或被狂风忽吹散，有时仍聚结青烟。",story:"",readings:{事业:"",姻缘:"",财运:"",健康:"",出行:"",家宅:"",学业:"",流年:""}},{id:13,level:"中平",title:"孟浩然寻梅",poem:"岭南初放一枝梅，片片晶莹入酒杯。却遇骑驴人早至，儿童背负占春魁。",story:"岭南梅花早开，有人将梅花入酒，恰逢骑驴之人先至，儿童背负梅花争得春日之先机。寓意机会稍纵即逝，遇事需留心先机。",readings:{事业:"缺少贵人相助时，事情不易成功；与人合作还需提防他人抢占先机。",姻缘:"需防第三者介入，感情不宜草率决定。",财运:"求财较难，且可能需要与人分利。",健康:"可能出现小病或慢性病，需注意身体状况。",出行:"出行有机会得到善意帮助。",家宅:"家宅平常，整体没有明显大碍。",学业:"",流年:"冬季及初春运势相对较佳。"}},{id:14,level:"中平",title:"陶渊明醉酒",poem:"为爱幽闲多种竹，买春赏雨在茅屋。醉时卧倒杏花边，怕听莺儿惊梦熟。",story:"",readings:{事业:"名利不宜贪求，应保持平常心。",姻缘:"婚姻方面较少如意之处。",财运:"财利微薄。",健康:"疾病有望逐渐好转。",出行:"出行需防小人口舌。",家宅:"家宅平常，宜修德积善。",学业:"",流年:""}},{id:15,level:"上吉",title:"唐明皇游月殿",poem:"仙槎一叶泛中流，月殿蟾宫任尔游。盈耳霓裳声暂歇，酒诗吟饮几时休。",story:"唐明皇传说曾乘仙舟游历月宫，听闻仙乐，学得霓裳羽衣曲而归。签中以月宫畅游、仙乐不绝，象征人生顺遂、荣华安乐，同时提醒不可过度沉迷享乐。",readings:{事业:"事业发展顺利，有望名成利就。",姻缘:"适合订婚或结婚，感情有成。",财运:"正财、偏财均有收获机会。",健康:"身体安康，疾病有望痊愈。",出行:"出行往来顺遂，容易称心如意。",家宅:"家道兴旺，家庭平安。",学业:"学习进展顺利，有望取得提升。",流年:""}},{id:16,level:"中吉",title:"牧童归家",poem:"天边鸦背夕阳回，陇外儿童跨犊来。羌笛频吹声切耳，短长腔调乐何哉。",story:"诗中描绘夕阳西下时，牧童骑牛归家，一路吹奏羌笛的田园景象，表现安宁、自在和知足。",readings:{事业:"少年时期努力耕耘，事业有望在后期取得成就。",姻缘:"姻缘将至，适合把握机会。",财运:"财运偏向晚成，宜踏实努力。",健康:"疾病最终有望痊愈。",出行:"出行归来有喜。",家宅:"家宅平安。",学业:"种瓜得瓜，学习需要付出努力。",流年:""}},{id:17,level:"中吉",title:"月下追贤",poem:"秋水蒹葭白露盈，盈庭月色浸阶清。清风吹动马铃响，响接晨钟不断声。",story:"",readings:{事业:"",姻缘:"",财运:"",健康:"",出行:"",家宅:"",学业:"",流年:""}},{id:18,level:"下下",title:"杜鹃",poem:"杜鹃啼血泪悲声，声怨霜寒梦乍惊。惊动异乡为异客，客心更触故园情。",story:"",readings:{事业:"谋望总体不利，做事需要谨慎。",姻缘:"婚姻不利，容易出现不和。",财运:"求财困难。",健康:"身体方面宜谨慎，遇病应及时处理。",出行:"出行往来多有忧虑，不宜贸然行动。",家宅:"家宅运势不佳。",学业:"",流年:""}},{id:19,level:"中吉",title:"伏羲画八卦",poem:"乾卦三连号太阳，潜龙勿用第一章。其中爻象能参透，百福骈臻大吉昌。",story:"传说伏羲观察天地自然之象，创制八卦，并以此教化人民。签诗引用乾卦“潜龙勿用”，提示刚强之中也需要懂得收敛和等待时机。",readings:{事业:"初期可能不太顺利，需要保持耐心。",姻缘:"与伴侣相处应注意言行，避免积累矛盾。",财运:"财运属于先苦后甜，需要耐心经营。",健康:"身体方面宜谨慎，有病需及时处理。",出行:"出行不宜急躁，注意控制情绪。",家宅:"家宅平常，宜积善修德。",学业:"",流年:"四季各有不同的小运，应根据形势决定进退。"}},{id:20,level:"中平",title:"天上仙花",poem:"天上仙花难问种，人间尘事几多更。前程已注公私簿，罚赏分明浊与清。",story:"诗中以天上仙花难以寻问其种、人间尘事变化繁多作比喻，并借公私簿记录善恶、赏罚分明，劝人守正修善。",readings:{事业:"名利得失不宜强求，应安分守己，踏实行事。",姻缘:"婚姻尚未确定，需要时间观察。",财运:"财利不可强求，应顺其自然。",健康:"患病应谨慎选择医生。",出行:"行善守正者可考虑出行。",家宅:"家宅平常，宜修身省察。",学业:"",流年:""}},{id:21,level:"中吉",title:"吴稳之会宴",poem:"天外红霞如抹锦，槛边桃杏斗新妆。盈眸烂熳谁居首，美酒频斟且酌量。",story:"",readings:{事业:"名利有望，但谋事不可急躁。",姻缘:"婚事宜从容，不宜急于定约。",财运:"",健康:"疾病渐有好转。",出行:"谨慎安排则有利。",家宅:"家宅有渐兴之象，宜修善。",学业:"",流年:""}},{id:22,level:"下下",title:"他乡作客",poem:"秋水伊人各一方，天南地北恨偏长。相思诗问凭谁寄，不尽凄凉几断肠。",story:"诗意写离居两地、音书难寄的相思愁苦。",readings:{事业:"谋望不利，宜等待时机，不宜急进。",姻缘:"婚姻不宜仓促求成。",财运:"",健康:"有病应谨慎求医，身心难安。",出行:"此时出行不利，宜慎重。",家宅:"家宅运势受阻，宜修善。",学业:"",流年:""}},{id:23,level:"中平",title:"梦中得宝",poem:"邯郸一梦幻无边，数载身荣是熟眠。换却锦衣归故里，睡醒还记在心田。",story:"",readings:{事业:"名利如虚花，谋望容易落空。",姻缘:"婚姻难成，不宜强求。",财运:"",健康:"疾病未能迅速痊愈，宜留意身体。",出行:"所得可能复失，出行宜谨慎。",家宅:"家宅平安，但整体运势平常。",学业:"",流年:""}},{id:24,level:"下下",title:"刘基归隐",poem:"诗酒琴棋可解愁，座中无客乐难休。或弹或唱谁知美，吟饮虽多亦是忧。",story:"",readings:{事业:"谋望恐惹忧愁，不宜贪求。",姻缘:"婚姻不宜强求。",财运:"求财求贵忌贪谋，宜谨慎。",健康:"疾病未愈，宜谨慎调养。",出行:"出行容易招忧，暂不宜贸然前往。",家宅:"家宅宜修德积善。",学业:"",流年:""}},{id:25,level:"上吉",title:"五岳泰山",poem:"群山扰扰朝中岳，有似为臣列鹄班。拱立两行齐整肃，自居此地岂无欢。",story:"以群山朝拱中岳比作臣子整齐列班，借此说明居于有利位置、得到众人响应的景象。",readings:{事业:"所求名利有望，谋事可获好结果。",姻缘:"婚事可以订立。",财运:"名利所求有应，财利可望。",健康:"遇到合适医生，疾病有望好转。",出行:"出行各处有贵人相助。",家宅:"家道兴盛。",学业:"",流年:""}},{id:26,level:"中平",title:"水月镜花",poem:"花影迟迟侵砌上，遥知月镜挂长空。忽闻鹤泪声凄切，早买归舟返里中。",story:"以花影、月色及鹤声为景，借闻不吉之声而及时买舟归乡，劝人知机避凶、及早回头。",readings:{事业:"谋事应观察时势，遇到不利迹象宜及早收手。",姻缘:"",财运:"",健康:"有病宜及早调养，并及早处理问题。",出行:"出行终究不甚适宜，宜审慎。",家宅:"家宅问题也应及早留意，见凶宜避。",学业:"",流年:""}},{id:27,level:"中平",title:"蚁子知时",poem:"天晴粉蝶翻衣晒，又看庭前蚁阵排。队伍整齐趋或退，时开时合思何佳。",story:"以蝴蝶晴天晒翼、蚂蚁将雨排阵为喻，说明万物各顺其时，行事应懂得进退。",readings:{事业:"谋事须观察时机，懂得进退。",姻缘:"婚事尚可，有机会相合。",财运:"财利微薄。",健康:"疾病可医治。",出行:"出行没有明显阻碍。",家宅:"家宅平常。",学业:"",流年:""}},{id:28,level:"中平",title:"白司马被贬",poem:"船泊浔阳月夜天，琵琶一曲动人怜。相思两地凭谁寄，白雪催人上鬓巅。",story:"白司马指白居易任江州司马时，夜闻琵琶之事；签诗借两地相思、白发催人的景象表达失意与愁苦。",readings:{事业:"功名难成，所谋之事不易实现。",姻缘:"婚姻不利，难有美满结果。",财运:"求财困难。",健康:"疾病痊愈较迟。",出行:"出行归来恐怕不尽如意。",家宅:"家宅艰辛，宜谨慎处理家中事务。",学业:"",流年:""}},{id:29,level:"中吉",title:"王羲之赏菊",poem:"鲈鱼作脍菊花黄，美酒盈樽近晚凉。泛棹正当潮上候，这般佳景乐无央。",story:"描绘鲈鱼、菊花、美酒与潮水俱备的秋日游乐景象，未明确提供对应人物的历史故事出处。",readings:{事业:"名望可期，谋事顺利。",姻缘:"婚姻相合。",财运:"求财有利。",健康:"疾病无大碍。",出行:"一路顺利。",家宅:"家宅平安。",学业:"",流年:""}},{id:30,level:"下下",title:"贵妃受劫",poem:"倾国倾城媚百生，六宫粉黛尽无名。马嵬山下魂飞去，至今明皇长恨情。",story:"唐玄宗宠爱杨贵妃，安史之乱时军队行至马嵬坡发生兵变，杨贵妃被迫自尽；唐玄宗此后长怀遗恨。",readings:{事业:"谋望不利，事情多有阻碍。",姻缘:"婚姻难成。",财运:"求财困难。",健康:"疾病未安，需谨慎处理。",出行:"出行不吉，不宜贸然前往。",家宅:"家宅有受劫之象，宜谨慎并修善。",学业:"",流年:""}},{id:31,level:"下下",title:"渔翁遇风失东西",poem:"狂风骤雨打船篷，溪畔桃花尽落红。惊醒渔翁春梦熟，持篙撑去失西东。",story:"签诗描写渔翁在春梦中被狂风骤雨惊醒，撑船时又失去方向；此比喻突遇惊险、仓促失措。",readings:{事业:"谋望多阻，切勿贸然行动。",姻缘:"婚姻不宜，难以成就。",财运:"财物有耗散之象。",健康:"疾病未安，身体需多加留意。",出行:"出行不宜。",家宅:"家宅运势不吉。",学业:"",流年:""}},{id:32,level:"中平",title:"苏武牧羊",poem:"十九年前海上辛，节旄雕败逐沙尘。餐毛嚼雪谁怜我，惟有羊儿作伴群。",story:"汉使苏武出使匈奴后被扣留，持节牧羊多年，历尽艰辛仍不改其志，后来得以归汉。",readings:{事业:"谋事艰难，名望不易达成。",姻缘:"",财运:"求财困难。",健康:"身体状况不易迅速好转，宜谨慎调养。",出行:"出行不利，行人归期较迟。",家宅:"家宅运势受阻。",学业:"",流年:""}},{id:33,level:"中平",title:"曹操走难",poem:"曹操虽有深谋计，智慧难瞒诸葛侯。试看东风都可借，更能流马木成牛。",story:"签题与解曰以曹操、诸葛亮为背景，提到诸葛亮借东风及制造木牛流马，说明奸谋终难得逞。",readings:{事业:"谋望难成，不宜使用欺诈或害人的手段。",姻缘:"婚姻不合，难称心意。",财运:"财利难有。",健康:"身体略有不安，宜谨慎照料。",出行:"出行恐有不利。",家宅:"家宅平常。",学业:"",流年:""}},{id:34,level:"中吉",title:"虞舜耕田",poem:"大舜虽耕在历山，心常孝顺两嚣顽。田中之象同家象，善恶分明即此间。",story:"",readings:{事业:"谋望有望，但应以善行、正道为先。",姻缘:"婚姻有缘，宜以诚相待。",财运:"求财可望，但应行善积德。",健康:"疾病痊愈较慢，宜谨慎调养。",出行:"可以出行，但仍应考虑周全。",家宅:"家宅平常，积善则昌。",学业:"",流年:""}},{id:35,level:"中吉",title:"唐僧取经",poem:"天将降任此其人，筋骨先劳苦彼身。莫谓景佳来可易，贫穷富贵有前因。",story:"诗句化用《孟子·告子下》“天将降大任于是人也”的意思，强调承担重任前往往先经历劳苦；签题另以唐僧取经作比。",readings:{事业:"名利不易求成，谋事须审慎选择并耐心努力。",姻缘:"婚姻有缘。",财运:"",健康:"疾病逐渐好转。",出行:"行人情况难以预测，出行进退须谨慎。",家宅:"家宅宜积德修善。",学业:"",流年:""}},{id:36,level:"中吉",title:"陶渊明归家",poem:"此事真如到岸船，何忧风水不相全。举头便见前村落，屋角阳斜爨已烟。",story:"",readings:{事业:"名利有望，谋事有机缘。",姻缘:"婚姻可成。",财运:"财利渐有收获。",健康:"疾病渐渐痊愈。",出行:"往来皆可喜，行人有归期。",家宅:"家宅有福。",学业:"",流年:""}},{id:37,level:"上吉",title:"王羲之钓鱼",poem:"月夜秋江下钓鳌，鱼形恰似四腮鲈。家藏旧酿堪盈斗，与友飞觞尽倒壶。",story:"描绘月夜钓得四腮鲈鱼，取出家藏旧酒与朋友畅饮的欢乐场景。",readings:{事业:"谋望顺利，百事亨通。",姻缘:"婚姻相合。",财运:"财利丰盈。",健康:"疾病有望痊愈。",出行:"出行到处合宜。",家宅:"家宅兴旺。",学业:"",流年:""}},{id:38,level:"中吉",title:"陶渊明辞官归隐",poem:"归去来兮仕官闲，室堪容膝亦为安。南窗寄傲谈诗酒，倚杖徘徊饱看山。",story:"陶渊明辞官归隐，居室虽小仍感安适；凭窗谈诗饮酒、扶杖看山，表现不贪名利、知足自在的生活态度。",readings:{事业:"名望难成，谋事须审时度势。",姻缘:"婚姻不合，不宜勉强。",财运:"财运渐有进展。",健康:"疾病可医治。",出行:"行人将至，出行仍须知所趋避。",家宅:"家宅平安，宜修善。",学业:"",流年:""}},{id:39,level:"中平",title:"夷齐让国",poem:"夷齐不忍食周粟，兄弟心甘采蕨餐。让国名应垂万古，可怜饿倒首阳山。",story:"伯夷、叔齐兄弟让国，隐居首阳山采蕨薇为食，不肯食周粟，最终饿死；其气节与悲苦并存。",readings:{事业:"谋望不易称心，宜忍耐并谨慎行事。",姻缘:"婚姻不宜强求。",财运:"求财困难。",健康:"疾病风险较高，宜及时求医。",出行:"出行恐有阻隔，不宜贸然前往。",家宅:"家宅平常。",学业:"",流年:""}},{id:40,level:"下下",title:"伯牙碎琴",poem:"人世知音能有几，碎琴都为子期亡。坟前洒尽千行泪，隔别阴阳各一方。",story:"伯牙善弹琴，钟子期善听；钟子期去世后，伯牙认为世间再无知音，遂在其墓前摔碎琴，不再弹奏。",readings:{事业:"谋望不利，暂不宜贸然向前。",姻缘:"婚姻无缘，难以成就。",财运:"求财不利。",健康:"疾病容易拖延，需谨慎处理。",出行:"出行没有明显好处，不宜前往。",家宅:"家宅不安，宜修德积善。",学业:"",流年:""}},{id:41,level:"中吉",title:"张骞遇仙姬",poem:"浮槎月夜到天河，曾见仙姬织锦梭。石得支机人罕识，那知此宝出云窝。",story:"张骞传说乘槎夜至天河，见仙女织锦并取得支机石而归；签文借此比喻自身有才宝，却未必为世人识得，终有机会遇到赏识者。",readings:{事业:"谋望之事应努力争取。",姻缘:"婚姻可合，姻缘将近。",财运:"求财合时。",健康:"有病宜祈祷。",出行:"出行无妨。",家宅:"家宅无碍，宜积善。",学业:"",流年:""}},{id:42,level:"中吉",title:"王允遇貂婵",poem:"月明散步到花栏，无策焉能剿灭奸。幸有貂婵思定国，英雄难过美人关。",story:"东汉末年，王允为铲除董卓而苦无良策，貂婵参与连环计，使董卓与吕布反目，最终促成董卓败亡。",readings:{事业:"谋望可吉，宜正直行事并防小人。",姻缘:"婚姻可合。",财运:"求财可得。",健康:"疾病有望痊愈。",出行:"出行宜防小人。",家宅:"家宅平安。",学业:"",流年:""}},{id:43,level:"下下",title:"韩文公谏君",poem:"只因直谏怒天颜，昼夜难离在马鞍。主仆奔忙神亦倦，更加雪重拥蓝关。",story:"韩愈因直言劝谏触怒皇帝，被贬赴潮州；途中行至蓝关又遇大雪阻路，描绘艰难困顿之境。",readings:{事业:"谋望多凶，不宜贸然推进。",姻缘:"婚姻不宜。",财运:"财运不遂。",健康:"疾病较难痊愈，应谨慎处理。",出行:"出行阻滞，事势艰难。",家宅:"家宅运势受阻。",学业:"",流年:""}},{id:44,level:"中吉",title:"唐天宝评花",poem:"满园春色斗新妆，意似争姘夺国香。到底是谁居丽首，牡丹艳冠百花场。",story:"唐玄宗天宝年间，牡丹为人所赏，以艳冠群芳、被评为百花之首的景象，寓意出众与得势。",readings:{事业:"有脱颖而出、趁势发展的机会。",姻缘:"感情运较佳，适合考虑婚事。",财运:"求财较以往顺利，但宜积蓄。",健康:"偶有小病，应及时就医。",出行:"",家宅:"家中喜事较多。",学业:"",流年:"立春后运势渐入佳境。"}},{id:45,level:"中平",title:"王质遇仙",poem:"采樵不意到云天，闲看敲棋二老仙。柯烂也思归故里，山中七日世千年。",story:"樵夫王质入山砍柴，偶遇仙人对弈，观棋片刻后发现斧柄已朽；回到人间时，世上已历经千年。",readings:{事业:"计划若不付诸行动，便难有成果。",姻缘:"感情运较好，宜珍惜相处时光。",财运:"财物须靠自身努力取得，不宜寄望侥幸。",健康:"宜多作户外活动。",出行:"",家宅:"家庭生活平稳，夫妻感情平淡而真挚。",学业:"",流年:"平稳中有机会，宜把握时机。"}},{id:46,level:"下下",title:"左慈戏曹",poem:"黄柑数盒献曹公，剖看原来肉尽空。怒动奸雄挥铁斧，奔忙身入万羊中。",story:"签文讲述有人献给曹操数盒柑橘，剖开后却发现柑内空无果肉，曹操震怒挥斧，献柑者逃入羊群中避祸；以此喻假局欺人、惹祸归身。",readings:{事业:"谋望之事不可行，名望难成。",姻缘:"婚姻未合。",财运:"财运不生。",健康:"疾病有险。",出行:"出行大为不利。",家宅:"家宅不宁。",学业:"",流年:""}},{id:47,level:"中平",title:"鲁肃索荆州",poem:"遥遥千里来西蜀，欲问荆州那日还。刘备不言声泪下，自思无策转吴间。",story:"三国时刘备向孙权借荆州，后来东吴派鲁肃索还；刘备以哭泣应对，仍无妥善解决办法。签意涉及借而不还及进退为难。",readings:{事业:"事业常有阻滞，不宜贸然自行开业。",姻缘:"感情容易因小事争端而进退两难。",财运:"钱财往来须谨慎，账目和文件宜亲自核对。",健康:"皮肤、肠胃等小病可能反复。",出行:"",家宅:"家宅平安，但须防财物损失。",学业:"",流年:"有小灾劫，登山涉水及财物往来须谨慎。"}},{id:48,level:"中平",title:"卓文君卖酒",poem:"绣阁听琴自起思，改妆夤夜最欢时。可怜沽酒临邛市，才子佳人两下厨。",story:"卓文君夜听司马相如弹琴而与之私奔；二人婚后家贫，在临邛开酒肆，夫妻共同经营。",readings:{事业:"做事宜亲力亲为，可考虑与可信任的伴侣合作。",姻缘:"感情运较佳，有良缘可把握。",财运:"没有偏财，收入须靠自身劳动。",健康:"大致无碍，但宜保持良好生活习惯。",出行:"",家宅:"夫妻同心，家庭关系可渐趋和睦。",学业:"",流年:"先苦后甜，冬季有贵人助力。"}},{id:49,level:"中吉",title:"司马相如题桥",poem:"十年窗下苦功成，有志难舒愿不轻。试看题桥十三字，生平心誓确钟情。",story:"司马相如未成名时在桥上题下志向，立誓若不能乘高车驷马便不再经过此桥；后来得汉武帝赏识，终有所成。",readings:{事业:"有白手创业、凭自身努力发展的机会。",姻缘:"感情美满，可主动表达结婚意愿。",财运:"年中正财较旺，也有偏财机会。",健康:"心情愉快，小病有望逐渐好转。",出行:"",家宅:"家庭境况渐有改善，夫妻感情趋于深厚。",学业:"",流年:"运势逐步向好，入秋后更佳。"}},{id:50,level:"中吉",title:"伍员出关",poem:"记得当年伍子胥，潜奔难渡幸逢渔。欲将宝剑相持赠，大义交朋却不辞。",story:"伍子胥遭楚王追杀，逃至江边时获渔父救助渡江；他欲赠宝剑答谢，渔父却辞而不受。",readings:{事业:"遇到困难时有贵人相助，但仍须坚定行事。",姻缘:"有机会遇到合意对象，宜尊重对方诚意。",财运:"财有来路，但切忌贪婪。",健康:"注意休息，秋冬宜多保养。",出行:"不宜贪图谋取，谨慎后再行。",家宅:"家人安康，宜孝顺父母、避免争吵。",学业:"读书须用功，方能有所成。",流年:"表面似有动荡，但其中仍有机会。"}},{id:51,level:"中平",title:"成王剪桐封弟",poem:"剪桐虽是作儿嬉，封弟成圭语不移。何以伪为成实事，言因无戏故如斯。",story:"周成王与弟弟戏言封侯，周公以“君无戏言”劝谏；后来成王兑现承诺，将唐地封给弟弟唐叔，故事强调言而有信。",readings:{事业:"做事须守时守信，谋定后再行动。",姻缘:"情侣容易争吵，宜坦诚沟通。",财运:"并非求财特别有利之年，宜为将来储备。",健康:"宜留意四肢损伤。",出行:"",家宅:"宜孝敬长辈、爱护晚辈。",学业:"",流年:"平平常常，但仍有小机会。"}},{id:52,level:"中平",title:"天地人三才",poem:"上清下浊成天地，清浊相凝便作人。尔欲签求明白事，且将三等细明分。",story:"签文以清气上浮成天、浊气下凝成地、清浊相合而成人作比喻，强调清浊善恶有别，行事应端正清洁。",readings:{事业:"谋望须谨慎行事。",姻缘:"婚事不宜贸然决定。",财运:"财利不丰。",健康:"疾病可医治。",出行:"行善者适宜出行，行事不正则不宜。",家宅:"积善可使家宅兴旺。",学业:"",流年:""}},{id:53,level:"中吉",title:"孟尝君",poem:"珠履三千客孟尝，谁人识得有膺扬。其中弹铗归来者，便是英雄志莫当。",story:"战国齐国孟尝君门下食客众多，冯谖曾弹剑而歌表达待遇不足；孟尝君后来礼遇他，显出识才与用才之意。",readings:{事业:"谋望之事尚需仔细商量，名利可望但宜修善。",姻缘:"婚姻可望良好。",财运:"",健康:"有病宜祈祷。",出行:"出行宜有得力之人扶助。",家宅:"家宅无碍。",学业:"",流年:""}},{id:54,level:"中平",title:"庄周梦蝶蜨",poem:"庄子酣眠成蜨梦，翩翻飞入百花丛。天香采得归来后，犹在高床暖枕中。",story:"庄周梦见自己化为蝴蝶，在花丛间飞舞；醒来后仍卧于床上，由此引出梦境与现实的思辨。",readings:{事业:"不宜期望过高，现实发展可能与预想有差距。",姻缘:"婚事暂缓较妥。",财运:"虽有小财，但不易积蓄。",健康:"身心较为开朗。",出行:"出行宜稳妥谨慎。",家宅:"家中气氛欢乐，家人平安。",学业:"勤奋有益，嬉戏无益。",流年:"平稳，无特别变化。"}},{id:55,level:"中平",title:"吴隐之除官归隐",poem:"浦号沉香遗旧恨，渡江犹忆古人心。可怜当日辞官去，虽有馨留不易寻。",story:"东晋吴隐之为官清廉，拒绝接受沉香馈赠；返程遇风浪时将沉香投入水中，以表明不取不义之财的操守。",readings:{事业:"谋望之事应仔细考虑。",姻缘:"婚事暂不宜议定。",财运:"有利可得，但贪心反受其害。",健康:"疾病可医治。",出行:"行善者可以出行。",家宅:"修善可得福。",学业:"",流年:""}},{id:56,level:"中吉",title:"桃木剑化龙",poem:"安知此剑不成龙，见水都应出袖中。他日飞腾千万里，上空妖矫有云从。",story:"签文描绘袖中之剑遇水化龙、日后飞腾万里的奇异景象；此象征吉兆，但指出“他日”意味着尚待时机。",readings:{事业:"谋望吉，名望可期。",姻缘:"婚姻可谋。",财运:"求财可望。",健康:"疾病有望痊愈。",出行:"出行可望顺意。",家宅:"家宅吉。",学业:"",流年:"年末更有喜色（问天时，尾季更可喜）。"}},{id:57,level:"中吉",title:"卖花得美",poem:"小楼春雨声初歇，彳亍街头屐不停。忽听卖花人入巷，一枝买得慢行行。",story:"春雨刚停，行人穿木屐在街上行走，听见卖花人入巷便买下一枝花；因路面湿滑而慢慢前行，寓意凡事从容谨慎。",readings:{事业:"谋望之事需要仔细。",姻缘:"婚姻可求，进展渐渐到来。",财运:"求财少量亦可满足。",健康:"疾病及孕事均宜谨慎。",出行:"出行凡事仔细则吉。",家宅:"家宅平安，将有喜事。",学业:"",流年:""}},{id:58,level:"下下",title:"秦穆公大败",poem:"秦师大败在殽山，三帅皆擒尽放还。蹇叔谏言因不听，倒戈舍甲返秦间。",story:"秦穆公不听蹇叔劝谏，出兵攻郑，在殽山遭晋军大败，三名主帅被俘后获释归秦；典故以不纳忠告、轻率出兵导致惨败为戒。",readings:{事业:"谋望之事不可行。",姻缘:"婚姻不利。",财运:"财运不利。",健康:"疾病有险。",出行:"出行风险较大。",家宅:"家宅未宁。",学业:"",流年:""}},{id:59,level:"下下",title:"吴王宠西施",poem:"浣溪纱女美无双，媚至吴王国破亡。最恼东施效颦笑，山鸡岂可胜鸾凰。",story:"越王勾践将西施献给吴王夫差，吴王沉迷美色而误国；东施模仿西施反而弄巧成拙，签文以此劝人安分守己，不宜盲目模仿他人。",readings:{事业:"谋望多不吉。",姻缘:"婚姻难有喜色。",财运:"求财困难。",健康:"疾病宜谨慎处理。",出行:"出行容易招来烦恼。",家宅:"家宅平常。",学业:"",流年:""}},{id:60,level:"中平",title:"李白醉和番书",poem:"和番醉笔似云烟，日在长安酒店眠。倘遇唐皇颁令召，重呼不上木兰船。",story:"传说李白醉卧长安酒肆，唐玄宗召其入宫处理和番文书；李白醒后挥笔成文，使番使不敢再来相扰。",readings:{事业:"事业暂未见明显起色。",姻缘:"适合考虑婚事。",财运:"财运微薄，不宜苛求。",健康:"小病无妨。",出行:"出行勿贪谋。",家宅:"家人平安。",学业:"多下苦功，成绩才有进步。",流年:"没有明显大机会，表面出现的机会未必可靠。"}},{id:61,level:"下下",title:"十二金牌召岳飞",poem:"十二金牌速召回，奸雄设计几时灰；可怜一旦功劳散，老少扶车不断哀。",story:"传说岳飞抗金时，秦桧以十二道金牌召其回朝，令其未能继续完成北伐，后遭奸臣构陷。此为",readings:{事业:"谋望之事不宜贸然进行。",姻缘:"婚姻不利。",财运:"容易破耗，不宜妄求。",健康:"病孕皆有辛苦，身体状况需谨慎。",出行:"未宜出行，并须防小人口舌。",家宅:"宅运不安，宜积善修德。",学业:"",流年:""}},{id:62,level:"中平",title:"美玉藏金",poem:"美玉于斯韞匱藏，休求善價費商量；沽之亦可隨相待，此物何须自看常。",story:"",readings:{事业:"谋望应等待合适时机，不宜急进。",姻缘:"婚姻不宜贸然议定。",财运:"求财须依正理，不可急求。",健康:"病愈较迟，宜耐心调养。",出行:"等待时机再出行。",家宅:"家宅吉，但仍宜修身行善。",学业:"",流年:""}},{id:63,level:"中吉",title:"颜回守道",poem:"陋巷箪瓢不足愁，旁人见此甚为忧；不知乐道忘贫之，亚圣芳名万古留。",story:"颜回生活清贫，居于陋巷，仅以一箪食、一瓢饮为食，却仍安于道义、乐于修身，因此受到后世尊崇。",readings:{事业:"谋望宜谨慎，不宜贪求名利。",姻缘:"婚姻可合。",财运:"不宜妄求名利；蚕畜之利可得。",健康:"疾病可医。",出行:"途中或有辛苦，最终苦中有甘。",家宅:"家宅吉。",学业:"",流年:""}},{id:64,level:"中吉",title:"孟之反奔",poem:"奔殿须知上古人，入门策马不夸能；败师谁肯甘从后，托谓鸣骢畏苦辛。",story:"鲁国与齐国交战失利，孟之反殿后撤退，入城后却不夸耀自己的功劳，谦称只是马跑不快；孔子曾称赞他的谦逊。",readings:{事业:"谋望应等待时机，不宜争强。",姻缘:"婚姻不宜。",财运:"名利难求，畜蚕须谨慎经营。",健康:"疾病宜谨慎求医祈福。",出行:"出行恐有不利，宜审慎。",家宅:"修善可使家宅趋美。",学业:"",流年:""}},{id:65,level:"下下",title:"陈后主失位",poem:"隋灭陈时战伐纷，都因妖媚闭明君；陈奔西赴无藏息，井里胭脂隐玉人。",story:"陈后主沉迷声色，隋军攻陈时仓皇逃亡，最终与妃嫔藏入胭脂井而被俘，陈朝随之复亡。",readings:{事业:"谋望不利，宜谨慎，避免冒进。",姻缘:"",财运:"有损耗，须防破财。",健康:"病情有险，须谨慎对待。",出行:"多有阻碍，不宜贸然出行。",家宅:"",学业:"",流年:""}},{id:66,level:"上吉",title:"王羲之会群贤",poem:"兰亭雅会众群贤，曲水流觞舍管弦；天朗气清风惠畅，茂林修竹乐怡然。",story:"王羲之曾于会稽山兰亭与众贤雅集，曲水流觞、饮酒赋诗；《兰亭序》记述的正是这一场景。",readings:{事业:"谋望吉利，诸事兴旺。",姻缘:"婚姻可定。",财运:"财运丰盈。",健康:"疾病有望痊愈。",出行:"往来皆吉利。",家宅:"家宅安宁。",学业:"",流年:""}},{id:67,level:"中平",title:"霸王自缢",poem:"人虽勇力不能当，莫恃英雄独冠场；可挟泰山超北海，身心犹贵重存亡。",story:"",readings:{事业:"谋望须仔细斟酌，不宜逞强。",姻缘:"婚姻不合。",财运:"财难得，不宜妄求。",健康:"有病宜谨慎求医祈祷。",出行:"出行凡事不可自恃，宜谨慎。",家宅:"家宅平常。",学业:"",流年:""}},{id:68,level:"中吉",title:"姜太公遇文王",poem:"久抱凌云志未舒，荷竿渭水钓游鱼；文王千里求贤士，灭纣兴周任意如。",story:"姜太公怀才未遇时隐居渭水垂钓，后来周文王前来求贤并任用他，最终辅佐周室兴起。",readings:{事业:"谋望适宜，等待贵人和时机。",姻缘:"婚姻可合。",财运:"求财可得。",健康:"疾病可医。",出行:"出行顺利。",家宅:"家宅平安。",学业:"",流年:""}},{id:69,level:"中吉",title:"韩文公祭鳄鱼",poem:"忠义存心官十载，年丰民乐惠难忘；鳄鱼毒害都能息，祷告长江北海王。",story:"韩愈任潮州刺史时，传说当地鳄鱼为害，韩愈作《祭鳄鱼文》祷告以止其害；注本借此说明忠义行事、为民造福。",readings:{事业:"谋望无大妨碍，可稳妥推进。",姻缘:"",财运:"求财大吉昌。",健康:"病孕之事宜谨慎祈禳。",出行:"忠直者可出行；行人渐有归期。",家宅:"家宅平稳，宜积善。",学业:"",流年:""}},{id:70,level:"中平",title:"塞翁失马",poem:"可比当年一塞翁，虽然失马半途中；不知祸福真何事，到底方明事始终。",story:"塞翁失马后，邻人以为是祸，他却认为未必；马后来归来又带马，儿子骑马跌伤，反而因此免于征役。故事用来说明祸福转化难以预料。",readings:{事业:"谋望不甚适宜，宜稳扎稳打。",姻缘:"暂不宜议定婚姻。",财运:"财利微薄。",健康:"疾病宜谨慎处理。",出行:"行人未至；行善者出行无妨。",家宅:"家宅安否暂难确定。",学业:"",流年:""}},{id:71,level:"中平",title:"庄周活鲋鱼",poem:"涸辙之中鲋困之，穷通自可卜当时；若能引得西江水，他日成龙也未知。",story:"鲋鱼困在干涸车辙中，向路人求水；庄周以此作比喻，说明身陷困境者亟需及时援助，否则难有转机。",readings:{事业:"谋望之事应等待时机。",姻缘:"婚姻暂不宜议。",财运:"财运难得。",健康:"有病应及时求医。",出行:"等待时机再出行。",家宅:"宅运受阻，宜积善修德。",学业:"",流年:""}},{id:72,level:"中平",title:"守株待兔",poem:"兔兒久待意何如，堪叹愚人独守株；算是无能令我笑，不须守旧自拘拘。",story:"有人守着树桩等待兔子再次撞来，久候无果仍不改变做法；故事用来劝人不要拘泥旧法、错失转机。",readings:{事业:"谋望之事暂不宜做，需考虑改变方法。",姻缘:"婚姻不宜。",财运:"财难得，蚕畜之利微薄。",健康:"疾病宜考虑另求诊治。",出行:"出行未必有利。",家宅:"家宅平常，宜修善。",学业:"",流年:""}},{id:73,level:"上上",title:"伦文叙高中",poem:"夹道花香衬马蹄，蓝袍改换锦衣归；满街红粉皆争羡，翘首芳名雁塔题。",story:"以进士、翰林题名及蓝袍换锦衣归乡的景象，说明功成名就、衣锦还乡；未据确认更具体的个人故事。",readings:{事业:"谋望大吉，有望取得显著成果。",姻缘:"",财运:"财大利。",健康:"疾病即愈。",出行:"出行事事合意。",家宅:"家宅兴旺，有贵气。",学业:"",流年:""}},{id:74,level:"下下",title:"朱买臣分妻",poem:"回忆当年运蹇时，夫妻反目两分离；名题雁塔归来候，复水马头时否悲。",story:"朱买臣家贫时妻子离去；后来朱买臣显达，妻子欲复合，但如复水难收，已无法挽回。",readings:{事业:"谋望不利，宜调整计划。",姻缘:"婚姻不利。",财运:"不宜求财，财利不佳。",健康:"病愈较迟，宜谨慎调养。",出行:"出行难获助力，不宜冒进。",家宅:"宅运受阻。",学业:"",流年:""}},{id:75,level:"下下",title:"伦文叙戏妻",poem:"婚姻岂可厌家贫，文叙夫妻两拆分；一旦首登龙虎榜，戏妻楼坠自身亡。",story:"传说，伦文叙家贫时妻子离去；他高中后戏谑旧妻，妻子因羞愤而坠楼身亡。",readings:{事业:"谋望之事不可贸然进行。",姻缘:"婚姻不宜成就。",财运:"财难得。",健康:"病难痊愈，宜及时就医。",出行:"出行不利。",家宅:"家宅不宁。",学业:"",流年:""}},{id:76,level:"中平",title:"孔夫子守道",poem:"人能乐道自修身，疏水曲肱岂厌贫；不义而富且贵者，我心都是作浮云。",story:"孔子即使生活清贫，饮水、枕着弯曲的手臂休息，仍能安于道义；不合道义取得的富贵，在他看来如浮云一般。",readings:{事业:"谋望多有商量与周折，不宜急进。",姻缘:"婚姻不宜勉强讲究。",财运:"名利勿贪，财利微薄。",健康:"",出行:"出行平淡，难有特别收获。",家宅:"家宅平常。",学业:"",流年:""}},{id:77,level:"中平",title:"公冶长受辱",poem:"鸟语能通公冶长，南山有个虎驮羊；其身虽在于缧绁，到底非关自己殃。",story:"传说公冶长通晓鸟语，听鸟说南山有虎拖羊，前往后被失主误以为偷羊而入狱；后来鸟传来消息使其得以证明清白、脱离牢狱。不同注本对获释过程的叙述略有差别。",readings:{事业:"谋望不甚适宜，宜守本分。",姻缘:"婚姻不合。",财运:"求财困难，不宜妄为。",健康:"疾病可医。",出行:"出行凶多吉少，行人归期较迟。",家宅:"宅运受阻，是非较多。",学业:"",流年:""}},{id:78,level:"上吉",title:"曾点言志",poem:"瑟希铿尔尚留声，春暮时刚春服成；冠五六人童六七，舞雩归咏畅幽情。",story:"曾点与孔子谈志向，描绘暮春时穿上春服，与几位成年朋友及少年到舞雩一带游赏，唱咏归来，表现自在闲适的心境。",readings:{事业:"谋望吉利，可按计划推进。",姻缘:"婚姻可求。",财运:"财利可得。",健康:"疾病无忧。",出行:"出行事事合意。",家宅:"家宅安乐。",学业:"",流年:""}},{id:79,level:"中平",title:"苏秦封相",poem:"富贵有如春梦熟，世人何苦力争求；任他秉笏当朝立，到死惟留土一抔。",story:"",readings:{事业:"谋望应等待时机，不宜强求。",姻缘:"暂不宜议婚。",财运:"不宜贪求名利，蚕畜之利微薄。",健康:"病孕之事宜谨慎祈佑。",出行:"出行劳苦而收益少。",家宅:"家宅平常，宜修德。",学业:"",流年:""}},{id:80,level:"中吉",title:"乐广释疑",poem:"飞觞对舞几时赊，弓影横杯误作蛇；猜透诗中元妙诀，泰来否极事无差。",story:"此签取“杯弓蛇影”故事：客人误把酒杯中映出的弓影当成蛇，心生疑惧；乐广解释后，客人释疑。故事借此提醒人不要因误会而自扰。",readings:{事业:"谋望合时，可按计划谨慎进行。",姻缘:"婚姻可合，但仍宜谨慎。",财运:"财可得，蚕畜之利微薄。",健康:"疾病可医。",出行:"出行最终无大妨碍。",家宅:"家宅平安，逐渐安稳。",学业:"",流年:""}},{id:81,level:"中吉",title:"子路射雌",poem:"山梁雌雉得其时，上下飞鸣自乐之。色举须知翔后集，作声三嗅过山欹。",story:"",readings:{事业:"谋望之事要审时知机。",姻缘:"",财运:"财可得。",健康:"孕与病均须仔细留意。",出行:"行人可归；出行事势可能有变化。",家宅:"家宅无大碍。",学业:"",流年:""}},{id:82,level:"中平",title:"孔子在卫",poem:"圣人击磬在于卫，谁料过门有荷篑。嗟叹有心挽道穷，可怜日月今将逝。",story:"孔子在卫国击磬，一位挑着草筐经过门口的人听见磬声，感叹击磬者有救世之心，却已年老；故事见于《论语·宪问》相关章句，亦作此解释。",readings:{事业:"谋望之事勿妄为。",姻缘:"婚姻不宜。",财运:"求财需等待时机。",健康:"病愈较迟。",出行:"行人尚未归；出行须防小人口舌。",家宅:"家宅平常。",学业:"",流年:""}},{id:83,level:"中平",title:"人心不足",poem:"凡尘身历几时闲，世事浑如叠叠山。既富尚忧无贵子，不知花放又花残。",story:"以赤松子劝人归隐为典故，借富贵之后仍有忧虑、花开花落的意象劝人知足；",readings:{事业:"谋望宜避免纷扰，不宜贪求名利。",姻缘:"婚姻暂不宜谋议。",财运:"",健康:"疾病可疗。",出行:"行人未至。",家宅:"家宅平安。",学业:"",流年:"一切平淡，勿担心，亦勿贪心。"}},{id:84,level:"中吉",title:"韩信投军",poem:"满腹奇才志未冲，铁鸡难举意无容。张良指示身投汉，项羽乌江命自穷。",story:"韩信怀才不遇时未获重用，后来经张良指引投奔汉王刘邦，辅佐汉军击败项羽；亦以此说明先难后易、终得贵人扶助。",readings:{事业:"谋望须审慎筹划，最终有望得到贵人扶助。",姻缘:"",财运:"财可得。",健康:"疾病可医。",出行:"行人渐至。",家宅:"家宅平安。",学业:"",流年:""}},{id:85,level:"上吉",title:"刘向高中",poem:"太乙燃藜照读书，十年窗下苦功舒。扬眉吐气袍穿锦，驷马高车拥道随。",story:"典故讲太乙神以藜杖照亮读书之处，象征长期苦读终获功名；以十年苦功后一朝显达说明此签。",readings:{事业:"谋望之事适合实行，名望可成。",姻缘:"婚姻可定。",财运:"财亦可得。",健康:"疾病可安。",出行:"行人归来，往来得意。",家宅:"家宅吉。",学业:"",流年:""}},{id:86,level:"中吉",title:"侃母迎宾",poem:"截发迎宾否也贫，贫中贤妇更何人。古今只有陶侃母，所以名留万代闻。",story:"陶侃家贫时有客来访，其母剪下自己的头发出售，换钱备酒待客；后世以此称颂陶母贤德。",readings:{事业:"谋望之事宜预先周详筹划。",姻缘:"婚姻可合。",财运:"财可求。",健康:"疾病可医。",出行:"行人归来，出行合时。",家宅:"家宅美。",学业:"",流年:"苦尽而甘来。"}},{id:87,level:"中平",title:"两雄相遇",poem:"会谈华座逞英雄，究竟谁人秉大公。一云日下荀鸣鹤，一说云间陆士龙。",story:"签诗提到荀氏、陆氏两位人物在席间各陈其说，众说纷纭，难辨谁能秉公判断；以此说明是非口舌、不可轻信传言。",readings:{事业:"谋望不甚适宜。",姻缘:"婚姻应另作考虑。",财运:"财难求。",健康:"疾病可医。",出行:"出行恐惹是非，行人未至。",家宅:"家宅须防是非。",学业:"",流年:""}},{id:88,level:"中吉",title:"木兰从军",poem:"替父从军胆气雄，须眉巾帼几人同。以身报国忠而孝，笑煞当时众巨公。",story:"花木兰代父从军，以女子之身上阵报国，兼尽忠孝；亦以此为典，勉人勇往向前、为善不辞劳苦。",readings:{事业:"谋望之事可以实行。",姻缘:"婚姻合宜。",财运:"财可求。",健康:"疾病可医。",出行:"行人归来，出行无妨。",家宅:"家宅平安。",学业:"",流年:""}},{id:89,level:"下下",title:"吴季子挂剑",poem:"他邦远历佩鱼肠，谁料徐君意欲将。既返愿为相赠答，且悬树下表情长。",story:"吴季札出使经过徐国，徐君喜爱其佩剑；季札当时未赠，待返回时徐君已逝，便将剑挂在墓旁树上，以表守信与长情。亦记载此事。",readings:{事业:"谋望之事不宜做。",姻缘:"婚姻暂莫议。",财运:"强求财利反而更困窘。",健康:"疾病有凶险。",出行:"行人不归，出行不宜求财。",家宅:"家宅平常，各尽本分。",学业:"",流年:""}},{id:90,level:"中平",title:"红拂女私奔",poem:"细整残妆夜欲奔，座中李靖更何人。那知虬髯情钟处，拔剑三回未敢陈。",story:"红拂女与李靖相知，准备夜间离开杨府；虬髯客出现后，李靖一度误会并欲拔剑，红拂女从中阻止。后世称三人为“风尘三侠”。",readings:{事业:"谋望之事不可为，功名须待时。",姻缘:"婚姻不宜。",财运:"财难得。",健康:"疾病可医，但孕事有惊险之虑。",出行:"行人归迟，出行财利勿相争。",家宅:"家宅平常。",学业:"",流年:"平淡中常有小喜，但大运未至。"}},{id:91,level:"上上",title:"蔡中兴高中",poem:"蟾官月殿桂飘香，玉箧团圆万里光。六水三山归镜里，无瑕一片挂穹苍。",story:"",readings:{事业:"谋望吉利。",姻缘:"婚姻相合。",财运:"求财可得，蚕畜可获大利。",健康:"疾病即愈。",出行:"行人即回，出行各处皆顺利。",家宅:"家宅平常。",学业:"",流年:"百事宜，整体顺遂。"}},{id:92,level:"中吉",title:"孔夫子周游列国",poem:"至圣周游列国行，在齐得听奏韶声。三月不知嘉肉味，善哉大道可功成。",story:"孔子周游列国时在齐国听到韶乐，专心学习，三个月沉浸其中而不知肉味；以专心致志终有所成为意。",readings:{事业:"谋望之事专心去做可望成功。",姻缘:"婚姻可合。",财运:"财可求。",健康:"疾病可医。",出行:"行人可至，出行有利。",家宅:"家宅安宁。",学业:"专心学习可望有成（据“专心去做则必功成”概括；非独立学业断语）。",流年:""}},{id:93,level:"下下",title:"郑王失位",poem:"郑卫之音不忍听，淫风败俗国将倾。令人深入迷津路，所奏全非古乐声。",story:"签诗借“郑卫之音”指不合礼乐的声乐风气，将其解释为败抔风俗、令人迷失，劝人谨慎并远离声色财利。",readings:{事业:"谋望之事不可为。",姻缘:"婚姻不宜。",财运:"财难求。",健康:"疾病痊愈较迟。",出行:"行人受阻，出行不利。",家宅:"宅运受阻，宜积善。",学业:"",流年:""}},{id:94,level:"中平",title:"两虎相争",poem:"一窟难藏两虎儿，乘风别岭各栖之。名山自守为巢穴，可免伤残后悔迟。",story:"以一山不能藏两虎为喻，劝双方知时退避、各守其位，避免争斗造成伤害；并非另有明确历史人物故事。",readings:{事业:"谋望之事须反复商量，不宜勉强。",姻缘:"婚姻不祥。",财运:"财难得。",健康:"疾病及孕事恐有损伤，须谨慎。",出行:"行人受阻，未能归乡；出行宜避开不利情势。",家宅:"家宅有碍，宜积善。",学业:"",流年:""}},{id:95,level:"中平",title:"女娲氏",poem:"功勤一篑可成山，由少而多莫惮烦。作事畏辛今汝画，补天炼石亦无难。",story:"传说远古时天穹出现破损，女娲炼五色石补天；签文借此勉励人持续勤奋、由少积多，终能完成艰难之事。",readings:{事业:"谋望应自强不息，勤恳做事。",姻缘:"婚姻不良，不宜急定。",财运:"求财平常。",健康:"疾病可医。",出行:"行人未至。",家宅:"家宅平常，积善可昌。",学业:"",流年:"可能有较大变动，勤力做事可平稳过度。"}},{id:96,level:"中平",title:"文姬思汉",poem:"姜笛频吹韵更悲，异乡作客触归期。南来孤雁如怜我，烦寄家书转达知。",story:"蔡文姬流落异乡，思念故国与家人；诗中借羌笛、孤雁和家书表现客居思归之情。重在客居难归的处境。",readings:{事业:"谋望之事不可为。",姻缘:"婚姻不宜。",财运:"财利未至。",健康:"疾病痊愈较迟。",出行:"行人未归，出行恐辛苦受阻。",家宅:"宅运受阻。",学业:"",流年:"凡事皆有阻滞。"}},{id:97,level:"中平",title:"康顺钓鱼",poem:"凭栏晚眺倚南楼，满目风光景色幽。一叶小舟频下饵，渔翁钓得有鱼无。",story:"以渔翁不断垂钓却未必有所收获为喻，说明勤苦未必有成，事情吉凶尚未可定。",readings:{事业:"谋望应谨慎。",姻缘:"婚姻宜另作选择。",财运:"财难得。",健康:"疾病痊愈较迟。",出行:"行人未至，出行辛苦恐无利。",家宅:"家宅平稳，修善可昌。",学业:"",流年:"勤苦未必有功，吉凶尚未可定。"}},{id:98,level:"中平",title:"掘地寻金",poem:"入山种玉嫌田狭，掘地寻金厌客多。富贵贫穷天注定，世人何苦力奔波。",story:"以田地狭小难以种玉、人多分薄难以掘金为喻，劝人修善听命，不要为富贵过度奔波。",readings:{事业:"谋望无大碍，但不宜强求；劳而无功之事不必前往。",姻缘:"婚姻不宜。",财运:"财难得。",健康:"疾病可医。",出行:"行人归迟，辛苦出行反而不美。",家宅:"家宅平稳。",学业:"",流年:"得失由天意，宜修善、不强求。"}},{id:99,level:"中平",title:"韩文公遇雪",poem:"雪拥桥头马不前，风狂渔父莫开船。水流花谢人谁惜，早立坚心志勿偏。",story:"以大雪阻马、狂风阻船为喻，提醒时机不利时不要勉强行动，及早立定正心，防止招惹是非。",readings:{事业:"谋望须等待时机，凡事谨慎。",姻缘:"婚姻不宜。",财运:"财难得。",健康:"患病应谨慎求医。",出行:"行人受阻，未能如期归来；出行易惹风波。",家宅:"家宅平常，宜结善缘。",学业:"",流年:"运势暂有阻隔，宜守正等待。"}},{id:100,level:"中吉",title:"百花开放",poem:"百花竞放贺阳春，万物从今尽转新。末数莫言穷运至，不知否极泰来频。",story:"以百花迎春、万物更新比喻运势由穷转通，提醒人在困顿时仍可改过向善、重新开始。",readings:{事业:"谋望可喜，运势有望逐渐转顺。",姻缘:"婚姻良好。",财运:"财运逐渐到来。",健康:"疾病渐愈。",出行:"行人渐归，出行可望转顺。",家宅:"家宅运转，行善则昌。",学业:"",流年:"否极泰来，困境有望逐步改善。"}}];
;
function validateHuangSigns(){const total=HUANG_DAXIAN_SIGNS.length,count={};HUANG_DAXIAN_SIGNS.forEach(s=>count[s.level]=(count[s.level]||0)+1);const ids=HUANG_DAXIAN_SIGNS.map(s=>s.id),dup=ids.filter((id,i)=>ids.indexOf(i)!==i),empty=HUANG_DAXIAN_SIGNS.filter(s=>!s.poem||s.poem.length<10||s.poem.includes("待录入"));console.log("黄大仙签自检:",{total,expected:100,count,expectedDist:HUANG_LEVEL_DIST,duplicateIds:dup,emptyOrPending:empty.length})}
;
function viewHuang(){const rec=DB.data.huang||{},pick2=rec.pick||null,hist=(DB.data.huangHistory||[]).slice(0,10),c=`<div class="p-panel tarot-module"><div class="yj-head"><div class="yj-kicker">黄大仙灵签</div><h2>黄大仙灵签</h2><p class="yj-note">心诚则灵，默念所问之事，在心中默想三遍后求签。共 100 签。</p></div>
  <section class="yj-card"><h3>求签</h3>
    <label class="fl">所问之事（可留空）</label>
    <input id="huang-q" type="text" maxlength="60" placeholder="如：近期事业运势" value="${esc(rec.question||"")}" style="width:100%;margin:6px 0 12px;background:var(--pt-input);border:1px solid var(--pt-border);border-radius:8px;padding:9px 12px;color:var(--pt-text);outline:none;font-size:14px">
    <div style="display:flex;gap:8px"><button class="btn btn-orange" id="huang-draw">求签</button>${pick2?'<button class="btn btn-ghost" id="huang-redraw">重新求签</button>':""}</div>
  </section>
  ${pick2?`<section class="yj-card huang-result"><div class="huang-num">第 ${pick2.id} 签</div><div class="huang-level lv-${pick2.level}">${pick2.level}</div><h3>${esc(pick2.title)}</h3><div class="huang-poem">${esc(pick2.poem)}</div><p class="huang-story"><b>典故：</b>${esc(pick2.story)}</p>
    <div class="huang-readings">${Object.entries(pick2.readings).map(([k,v])=>{const q=rec.question||"";return`<details ${k==="事业"&&/工作|事业|求职|创业/i.test(q)||k==="姻缘"&&/感情|姻缘|恋爱|婚姻/i.test(q)||k==="财运"&&/钱|财运|投资/i.test(q)?"open":""}><summary>${k}</summary><p>${esc(v)}</p></details>`}).join("")}</div>
  </section>`:""}
  ${hist.length?`<section class="yj-card"><h3>最近求签记录</h3><div class="yj-hist">${hist.map((h,i)=>`<div class="yj-hist-item" style="cursor:default"><small>${esc(h.time)}</small><b>第 ${h.id} 签 · ${h.level}</b><span>${esc(h.question||"")}</span></div>`).join("")}</div></section>`:""}
  </div>`;return portalShell("huang",c)}
;
function huangDraw(){var _a;const q=(((_a=$("#huang-q"))==null?void 0:_a.value)||"").trim(),shuffled=HUANG_DAXIAN_SIGNS.slice();for(let i=shuffled.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[shuffled[i],shuffled[j]]=[shuffled[j],shuffled[i]]}const pick2=shuffled[0],hist=DB.data.huangHistory||(DB.data.huangHistory=[]);hist.unshift({id:pick2.id,level:pick2.level,question:q,time:new Date().toLocaleString("zh-CN",{month:"numeric",day:"numeric",hour:"2-digit",minute:"2-digit"})}),hist.length>10&&(hist.length=10),DB.data.huang={question:q,pick:pick2,drawnAt:Date.now()},DB.save()}
